{"command":"mkdir testpkg
cd testpkg
go mod init testpkg
cat <<'EOF' > main.go
package main

import (
	"errors"
	"fmt"
	"os"
)

func main() {
	err := doSomething()
	if err != nil {
		fmt.Println(err)
	}
}

func doSomething() error {
	_, err := os.Open("nonexistent")
	if err != nil {
		return err // should be reported
	}
	return nil
}

func doSomethingWrapped() error {
	_, err := os.Open("nonexistent")
	if err != nil {
		return fmt.Errorf("failed: %w", err) // should NOT be reported
	}
	return nil
}

func internalError() error {
    return errors.New("internal error") // should NOT be reported by default?
}
EOF
go build .
"}

