{"command":"mkdir -p testpkg/internalpkg
cat <<'EOF' > testpkg/internalpkg/internal.go
package internalpkg

import "errors"

func DoInternal() error {
    return errors.New("internal error")
}
EOF

cat <<'EOF' > testpkg/main.go
package main

import (
	"fmt"
	"os"
    "testpkg/internalpkg"
)

func main() {
	err := doSomething()
	if err != nil {
		fmt.Println(err)
	}
}

func doSomething() error {
	_, err := os.Open("nonexistent")
	if err != nil {
		return err // should be reported
	}
	return nil
}

func doInternal() error {
    err := internalpkg.DoInternal()
    if err != nil {
        return err // should NOT be reported by default as it's from the same module?
    }
    return nil
}
EOF
cd testpkg && ../executable ./...
"}

