{"command":"cat <<'EOF' > main.go
package main

import (
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/passes/inspect"
	"golang.org/x/tools/go/analysis/singlechecker"
	"golang.org/x/tools/go/ast/inspector"
)

type config struct {
	IgnoreSigs             []string
	IgnoreSigRegexps       []string
	IgnorePackageGlobs     []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors   bool
}

var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

func loadConfig() config {
	c := config{
		IgnoreSigs: defaultIgnoreSigs,
	}
	data, err := os.ReadFile(".wrapcheck.yaml")
	if err != nil {
		home, _ := os.UserHomeDir()
		data, err = os.ReadFile(filepath.Join(home, ".wrapcheck.yaml"))
	}
	if err == nil {
		parseYAML(string(data), &c)
	}
	return c
}

func parseYAML(data string, c *config) {
	lines := strings.Split(data, "\n")
	var currentKey string
	var extraIgnoreSigs []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.HasPrefix(trimmed, "-") {
			val := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
			val = strings.Trim(val, `"'`)
			switch currentKey {
			case "ignoreSigs":
				c.IgnoreSigs = append(c.IgnoreSigs, val)
			case "extraIgnoreSigs":
				extraIgnoreSigs = append(extraIgnoreSigs, val)
			case "ignoreSigRegexps":
				c.IgnoreSigRegexps = append(c.IgnoreSigRegexps, val)
			case "ignorePackageGlobs":
				c.IgnorePackageGlobs = append(c.IgnorePackageGlobs, val)
			case "ignoreInterfaceRegexps":
				c.IgnoreInterfaceRegexps = append(c.IgnoreInterfaceRegexps, val)
			}
			continue
		}
		parts := strings.SplitN(trimmed, ":", 2)
		if len(parts) >= 1 {
			key := strings.TrimSpace(parts[0])
			if len(parts) == 2 && strings.TrimSpace(parts[1]) != "" {
				val := strings.TrimSpace(parts[1])
				if key == "reportInternalErrors" {
					c.ReportInternalErrors = (val == "true")
				}
			} else {
				currentKey = key
				if key == "ignoreSigs" {
					c.IgnoreSigs = nil
				}
			}
		}
	}
	c.IgnoreSigs = append(c.IgnoreSigs, extraIgnoreSigs...)
}

var errorInterface *types.Interface

func init() {
	errorInterface = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Implements(t, errorInterface)
}

var Analyzer = &analysis.Analyzer{
	Name:     "wrapcheck",
	Doc:      "Checks that errors returned from external packages are wrapped",
	Run:      run,
	Requires: []*analysis.Analyzer{inspect.Analyzer},
}

type assignment struct {
	pos   int
	obj   types.Object
	rhs   ast.Expr
}

func run(pass *analysis.Pass) (interface{}, error) {
	conf := loadConfig()
	ins := pass.ResultOf[inspect.Analyzer].(*inspector.Inspector)

	// Collect assignments in each file
	fileAssigns := make(map[*ast.File][]assignment)
	for _, file := range pass.Files {
		var assigns []assignment
		ast.Inspect(file, func(n ast.Node) bool {
			switch stmt := n.(type) {
			case *ast.AssignStmt:
				for _, lhs := range stmt.Lhs {
					if ident, ok := lhs.(*ast.Ident); ok {
						if obj := pass.TypesInfo.ObjectOf(ident); obj != nil {
							assigns = append(assigns, assignment{
								pos: int(ident.Pos()),
								obj: obj,
								rhs: stmt.Rhs[0], // Simplified
							})
						}
					}
				}
			case *ast.ValueSpec:
				for i, name := range stmt.Names {
					if obj := pass.TypesInfo.ObjectOf(name); obj != nil {
						if i < len(stmt.Values) {
							assigns = append(assigns, assignment{
								pos: int(name.Pos()),
								obj: obj,
								rhs: stmt.Values[i],
							})
						}
					}
				}
			}
			return true
		})
		fileAssigns[file] = assigns
	}

	ins.Preorder([]ast.Node{(*ast.ReturnStmt)(nil)}, func(n ast.Node) {
		ret := n.(*ast.ReturnStmt)
		var currentFile *ast.File
		for _, f := range pass.Files {
			if ret.Pos() >= f.Pos() && ret.Pos() <= f.End() {
				currentFile = f
				break
			}
		}
		if currentFile == nil {
			return
		}

		for _, res := range ret.Results {
			if !isErrorType(pass.TypesInfo.TypeOf(res)) {
				continue
			}
			call, sig := findSourceCall(pass, res, fileAssigns[currentFile])
			if call == nil {
				continue
			}

			if isIgnored(sig, conf) {
				continue
			}

			obj := getCallObj(pass, call)
			if obj == nil {
				continue
			}

			pkg := obj.Pkg()
			if pkg != nil && isPackageIgnored(pkg.Path(), conf) {
				continue
			}

			if pkg != nil && pkg.Path() != pass.Pkg.Path() {
				pass.Reportf(res.Pos(), "error returned from external package is unwrapped: sig: %s", sig)
				continue
			}

			if isInterfaceCall(pass, call) {
				ifaceName := getInterfaceName(pass, call)
				if !isInterfaceIgnored(ifaceName, conf) {
					pass.Reportf(res.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
					continue
				}
			}

			if conf.ReportInternalErrors {
				pass.Reportf(res.Pos(), "package-internal error should be wrapped: sig: %s", sig)
			}
		}
	})

	return nil, nil
}

func findSourceCall(pass *analysis.Pass, e ast.Expr, assigns []assignment) (*ast.CallExpr, string) {
	switch expr := e.(type) {
	case *ast.CallExpr:
		return expr, getSignature(pass, expr)
	case *ast.Ident:
		obj := pass.TypesInfo.Uses[expr]
		if obj == nil {
			return nil, ""
		}
		var bestAssign ast.Expr
		bestPos := -1
		for _, a := range assigns {
			if a.obj == obj && a.pos < int(expr.Pos()) {
				if a.pos > bestPos {
					bestPos = a.pos
					bestAssign = a.rhs
				}
			}
		}
		if call, ok := bestAssign.(*ast.CallExpr); ok {
			return call, getSignature(pass, call)
		}
	}
	return nil, ""
}

func getCallObj(pass *analysis.Pass, call *ast.CallExpr) types.Object {
	var obj types.Object
	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if selection, ok := pass.TypesInfo.Selections[sel]; ok {
			obj = selection.Obj()
		} else {
			obj = pass.TypesInfo.Uses[sel.Sel]
		}
	} else if ident, ok := call.Fun.(*ast.Ident); ok {
		obj = pass.TypesInfo.Uses[ident]
	}
	return obj
}

func getSignature(pass *analysis.Pass, call *ast.CallExpr) string {
	obj := getCallObj(pass, call)
	if obj == nil {
		return ""
	}
	return formatSignature(obj)
}

func formatSignature(obj types.Object) string {
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	sig := fn.Type().(*types.Signature)

	var b strings.Builder
	b.WriteString("func ")
	if sig.Recv() != nil {
		b.WriteString("(")
		b.WriteString(formatType(sig.Recv().Type()))
		b.WriteString(").")
	} else if pkg := obj.Pkg(); pkg != nil {
		b.WriteString(pkg.Path())
		b.WriteString(".")
	}
	b.WriteString(obj.Name())
	b.WriteString("(")
	params := sig.Params()
	for i := 0; i < params.Len(); i++ {
		if i > 0 {
			b.WriteString(", ")
		}
		p := params.At(i)
		if p.Name() != "" {
			b.WriteString(p.Name())
			b.WriteString(" ")
		}
		if sig.Variadic() && i == params.Len()-1 {
			b.WriteString("...")
			b.WriteString(formatType(p.Type().(*types.Slice).Elem()))
		} else {
			b.WriteString(formatType(p.Type()))
		}
	}
	b.WriteString(") ")
	res := sig.Results()
	if res.Len() == 1 && res.At(0).Name() == "" {
		b.WriteString(formatType(res.At(0).Type()))
	} else if res.Len() > 0 {
		b.WriteString("(")
		for i := 0; i < res.Len(); i++ {
			if i > 0 {
				b.WriteString(", ")
			}
			r := res.At(i)
			if r.Name() != "" {
				b.WriteString(r.Name())
				b.WriteString(" ")
			}
			b.WriteString(formatType(r.Type()))
		}
		b.WriteString(")")
	}
	return b.String()
}

func formatType(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		return p.Path()
	})
}

func isIgnored(sig string, conf config) bool {
	for _, s := range conf.IgnoreSigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, r := range conf.IgnoreSigRegexps {
		if match, _ := regexp.MatchString(r, sig); match {
			return true
		}
	}
	return false
}

func isPackageIgnored(pkgPath string, conf config) bool {
	for _, pattern := range conf.IgnorePackageGlobs {
		if match, _ := filepath.Match(pattern, pkgPath); match {
			return true
		}
	}
	return false
}

func isInterfaceCall(pass *analysis.Pass, call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	selection, ok := pass.TypesInfo.Selections[sel]
	if !ok {
		return false
	}
	if selection.Recv() == nil {
		return false
	}
	_, ok = selection.Recv().Underlying().(*types.Interface)
	return ok
}

func getInterfaceName(pass *analysis.Pass, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	selection, ok := pass.TypesInfo.Selections[sel]
	if !ok {
		return ""
	}
	t := selection.Recv()
	if t == nil {
		return ""
	}
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Name()
	}
	return t.String()
}

func isInterfaceIgnored(name string, conf config) bool {
	for _, r := range conf.IgnoreInterfaceRegexps {
		if match, _ := regexp.MatchString(r, name); match {
			return true
		}
	}
	return false
}

func main() {
	singlechecker.Main(Analyzer)
}
EOF

