	obj := getCallObj(pass, call)
	if obj == nil {
		return ""
	}
	return formatSignature(obj)
}

func formatSignature(obj types.Object) string {
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	sig := fn.Type().(*types.Signature)

	var b strings.Builder
	b.WriteString("func ")
	if sig.Recv() != nil {
		b.WriteString("(")
		b.WriteString(formatType(sig.Recv().Type()))
		b.WriteString(").")
	} else if pkg := obj.Pkg(); pkg != nil {
		b.WriteString(pkg.Path())
		b.WriteString(".")
	}
	b.WriteString(obj.Name())
	b.WriteString("(")
	params := sig.Params()
	for i := 0; i < params.Len(); i++ {
		if i > 0 {
			b.WriteString(", ")
		}
		p := params.At(i)
		if p.Name() != "" {
			b.WriteString(p.Name())
			b.WriteString(" ")
		}
		if sig.Variadic() && i == params.Len()-1 {
			b.WriteString("...")
			b.WriteString(formatType(p.Type().(*types.Slice).Elem()))
		} else {
			b.WriteString(formatType(p.Type()))
		}
	}
	b.WriteString(") ")
	res := sig.Results()
	if res.Len() == 1 && res.At(0).Name() == "" {
		b.WriteString(formatType(res.At(0).Type()))
	} else if res.Len() > 0 {
		b.WriteString("(")
		for i := 0; i < res.Len(); i++ {
			if i > 0 {
				b.WriteString(", ")
			}
			r := res.At(i)
			if r.Name() != "" {
				b.WriteString(r.Name())
				b.WriteString(" ")
			}
			b.WriteString(formatType(r.Type()))
		}
		b.WriteString(")")
	}
	return b.String()
}

func formatType(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		return p.Path()
	})
}

func isIgnored(sig string, conf config) bool {
	for _, s := range conf.IgnoreSigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, r := range conf.IgnoreSigRegexps {
		if match, _ := regexp.MatchString(r, sig); match {
			return true
		}
	}
	return false
}

func isPackageIgnored(pkgPath string, conf config) bool {
	for _, pattern := range conf.IgnorePackageGlobs {
		if match, _ := filepath.Match(pattern, pkgPath); match {
			return true
		}
	}
	return false
}

func isInterfaceCall(pass *analysis.Pass, call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	selection, ok := pass.TypesInfo.Selections[sel]
	if !ok {
		return false
	}
	if selection.Recv() == nil {
		return false
	}
	_, ok = selection.Recv().Underlying().(*types.Interface)
	return ok
}

func getInterfaceName(pass *analysis.Pass, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	selection, ok := pass.TypesInfo.Selections[sel]
	if !ok {
		return ""
	}
	t := selection.Recv()
	if t == nil {
		return ""
	}
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Name()
	}
	return t.String()
}

func isInterfaceIgnored(name string, conf config) bool {
	for _, r := range conf.IgnoreInterfaceRegexps {
		if match, _ := regexp.MatchString(r, name); match {
			return true
		}
	}
	return false
}

func main() {
	singlechecker.Main(Analyzer)
}
