	flag.String("cpuprofile", "", "write CPU profile to this file")
	flag.String("debug", "", "debug flags")
	flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	flag.Bool("fix", false, "apply all suggested fixes")
	flag.Bool("flags", false, "print analyzer flags in JSON")
	flag.Bool("json", false, "emit JSON output")
	flag.String("memprofile", "", "write memory profile to this file")
	flag.Bool("source", false, "no effect")
	flag.String("tags", "", "no effect")
	flag.String("trace", "", "write trace log to this file")
	flag.Bool("v", false, "no effect")
	flag.Parse()

	if flag.Arg(0) == "" {
		// No packages specified, default to current dir
		analyzePackage(".", *testFlag)
		return
	}

	for _, pkg := range flag.Args() {
		if strings.HasSuffix(pkg, "/...") {
			analyzeRecursive(strings.TrimSuffix(pkg, "/..."), *testFlag)
		} else {
			analyzePackage(pkg, *testFlag)
		}
	}
}

func analyzeRecursive(path string, includeTests bool) {
	filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			// Check if directory contains .go files
			files, _ := filepath.Glob(filepath.Join(p, "*.go"))
			if len(files) > 0 {
				analyzePackage(p, includeTests)
			}
		}
		return nil
	})
}

func analyzePackage(path string, includeTests bool) {
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, path, func(info os.FileInfo) bool {
		if !includeTests && strings.HasSuffix(info.Name(), "_test.go") {
			return false
		}
		return true
	}, parser.ParseComments)
	if err != nil {
		return
	}

	conf := loadConfig()
	for _, pkg := range pkgs {
		var files []*ast.File
		for _, f := range pkg.Files {
			files = append(files, f)
		}

		typeConfig := types.Config{Importer: importer.Default()}
		info := &types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Uses:       make(map[*ast.Ident]types.Object),
			Defs:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		}
		tPkg, err := typeConfig.Check(pkg.Name, fset, files, info)
		if err != nil {
			// If type checking fails, we still try to analyze what we can
			// but some info might be missing.
		}

		analyze(fset, tPkg, info, files, conf)
	}
}

func analyze(fset *token.FileSet, pkg *types.Package, info *types.Info, files []*ast.File, conf config) {
	errorInterface := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

	for _, file := range files {
		var assigns []assignment
		ast.Inspect(file, func(n ast.Node) bool {
			switch stmt := n.(type) {
			case *ast.AssignStmt:
				for _, lhs := range stmt.Lhs {
					if ident, ok := lhs.(*ast.Ident); ok {
						if obj := info.ObjectOf(ident); obj != nil {
							assigns = append(assigns, assignment{
								pos: int(ident.Pos()),
								obj: obj,
								rhs: stmt.Rhs[0],
							})
						}
					}
				}
			case *ast.ValueSpec:
				for i, name := range stmt.Names {
					if obj := info.ObjectOf(name); obj != nil {
						if i < len(stmt.Values) {
							assigns = append(assigns, assignment{
								pos: int(name.Pos()),
								obj: obj,
								rhs: stmt.Values[i],
							})
						}
					}
				}
			}
			return true
		})

		ast.Inspect(file, func(n ast.Node) bool {
			ret, ok := n.(*ast.ReturnStmt)
			if !ok {
				return true
			}
			for _, res := range ret.Results {
				t := info.TypeOf(res)
				if t == nil || !types.Implements(t, errorInterface) {
					continue
				}

				call, sig := findSourceCall(info, res, assigns)
				if call == nil {
					continue
				}

				if isIgnored(sig, conf) {
					continue
				}

				obj := getCallObj(info, call)
				if obj == nil {
					continue
				}

				callPkg := obj.Pkg()
				if callPkg != nil && isPackageIgnored(callPkg.Path(), conf) {
					continue
				}

				if callPkg != nil && pkg != nil && callPkg.Path() != pkg.Path() {
					fmt.Printf("%s: error returned from external package is unwrapped: sig: %s\n", fset.Position(res.Pos()), sig)
					os.Exit(3)
					continue
				}

				if isInterfaceCall(info, call) {
					ifaceName := getInterfaceName(info, call)
					if !isInterfaceIgnored(ifaceName, conf) {
						fmt.Printf("%s: error returned from interface method should be wrapped: sig: %s\n", fset.Position(res.Pos()), sig)
						os.Exit(3)
						continue
					}
				}

				if conf.ReportInternalErrors {
					fmt.Printf("%s: package-internal error should be wrapped: sig: %s\n", fset.Position(res.Pos()), sig)
					os.Exit(3)
				}
			}
			return true
		})
	}
}

type assignment struct {
	pos int
	obj types.Object
	rhs ast.Expr
}

func findSourceCall(info *types.Info, e ast.Expr, assigns []assignment) (*ast.CallExpr, string) {
	switch expr := e.(type) {
	case *ast.CallExpr:
		return expr, getSignature(info, expr)
	case *ast.Ident:
		obj := info.Uses[expr]
		if obj == nil {
			return nil, ""
		}
		var bestAssign ast.Expr
		bestPos := -1
		for _, a := range assigns {
			if a.obj == obj && a.pos < int(expr.Pos()) {
				if a.pos > bestPos {
					bestPos = a.pos
					bestAssign = a.rhs
				}
			}
		}
		if call, ok := bestAssign.(*ast.CallExpr); ok {
			return call, getSignature(info, call)
		}
	}
	return nil, ""
}

func getCallObj(info *types.Info, call *ast.CallExpr) types.Object {
	var obj types.Object
	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if selection, ok := info.Selections[sel]; ok {
			obj = selection.Obj()
		} else {
			obj = info.Uses[sel.Sel]
		}
	} else if ident, ok := call.Fun.(*ast.Ident); ok {
		obj = info.Uses[ident]
	}
	return obj
}

func getSignature(info *types.Info, call *ast.CallExpr) string {
	obj := getCallObj(info, call)
	if obj == nil {
		return ""
	}
	return formatSignature(obj)
}

func formatSignature(obj types.Object) string {
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	sig := fn.Type().(*types.Signature)

	var b strings.Builder
	b.WriteString("func ")
	if sig.Recv() != nil {
		b.WriteString("(")
		b.WriteString(formatType(sig.Recv().Type()))
		b.WriteString(").")
	} else if pkg := obj.Pkg(); pkg != nil {
		b.WriteString(pkg.Path())
		b.WriteString(".")
	}
	b.WriteString(obj.Name())
	b.WriteString("(")
	params := sig.Params()
	for i := 0; i < params.Len(); i++ {
		if i > 0 {
			b.WriteString(", ")
		}
		p := params.At(i)
		if p.Name() != "" {
			b.WriteString(p.Name())
			b.WriteString(" ")
		}
		if sig.Variadic() && i == params.Len()-1 {
			b.WriteString("...")
			b.WriteString(formatType(p.Type().(*types.Slice).Elem()))
		} else {
			b.WriteString(formatType(p.Type()))
		}
	}
	b.WriteString(") ")
	res := sig.Results()
	if res.Len() == 1 && res.At(0).Name() == "" {
		b.WriteString(formatType(res.At(0).Type()))
	} else if res.Len() > 0 {
		b.WriteString("(")
		for i := 0; i < res.Len(); i++ {
			if i > 0 {
				b.WriteString(", ")
			}
			r := res.At(i)
			if r.Name() != "" {
				b.WriteString(r.Name())
				b.WriteString(" ")
			}
			b.WriteString(formatType(r.Type()))
		}
		b.WriteString(")")
	}
	return b.String()
}

func formatType(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		return p.Path()
	})
}

func isIgnored(sig string, conf config) bool {
	for _, s := range conf.IgnoreSigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, r := range conf.IgnoreSigRegexps {
		if match, _ := regexp.MatchString(r, sig); match {
			return true
		}
	}
	return false
}

func isPackageIgnored(pkgPath string, conf config) bool {
	for _, pattern := range conf.IgnorePackageGlobs {
		if match, _ := filepath.Match(pattern, pkgPath); match {
			return true
		}
	}
	return false
}

func isInterfaceCall(info *types.Info, call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	selection, ok := info.Selections[sel]
	if !ok {
		return false
	}
	if selection.Recv() == nil {
		return false
	}
	_, ok = selection.Recv().Underlying().(*types.Interface)
	return ok
}

func getInterfaceName(info *types.Info, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	selection, ok := info.Selections[sel]
	if !ok {
		return ""
	}
	t := selection.Recv()
	if t == nil {
		return ""
	}
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Name()
	}
	return t.String()
}

func isInterfaceIgnored(name string, conf config) bool {
	for _, r := range conf.IgnoreInterfaceRegexps {
		if match, _ := regexp.MatchString(r, name); match {
			return true
		}
	}
	return false
}
